32	    img, svg, video, canvas, picture { max-width: 100%; display: block; }
33	    img, video { height: auto; }
34	    pre, code, kbd, samp { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.9em; }
35	    pre { overflow-x: auto; tab-size: 2; }
36	    th, td { padding: 0.25em 0.5em; text-align: start; vertical-align: top; }
37	    sub, sup { line-height: 0; }
38	    a { text-underline-offset: 0.15em; }
39	    button:not(:disabled), [role="button"], summary, label[for] { cursor: pointer; }
40	    textarea { resize: vertical; }
41	    [hidden] { display: none !important; }
42	    :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
43	    @media (prefers-reduced-motion: reduce) {
44	      *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
